/* Ядро плагина «Передача задач».
 *
 * Данные плагина хранятся в собственном блобе (persistDataSynced) и едут через
 * ту же синхронизацию, что и остальные данные Super Productivity — то есть
 * через общий файл в сетевой папке.
 *
 * Внутри — журнал операций (append-only). С файлом одновременно работают
 * несколько человек, поэтому состояние не пишется целиком: операции
 * неизменяемы и уникальны по id, слияние двух версий — объединение множеств.
 * Так правки коллег не затирают друг друга.
 *
 * Сами задачи в этом журнале не дублируются — ими владеет Super Productivity.
 * Ответственный обозначается тегом участника, журнал хранит только участников
 * и передачи.
 */
(function (глобальный) {
  'use strict';

  var ВЕРСИЯ_ДАННЫХ = 1;

  var ТИПЫ = {
    УЧАСТНИК: 'user.upsert',
    ПРЕДЛОЖЕНИЕ: 'offer.create',
    ПРИНЯТИЕ: 'offer.accept',
    ОТКЛОНЕНИЕ: 'offer.reject',
    ОТЗЫВ: 'offer.cancel',
  };

  function новыйId(префикс) {
    var буфер = new Uint8Array(9);
    (глобальный.crypto || {}).getRandomValues
      ? глобальный.crypto.getRandomValues(буфер)
      : буфер.forEach(function (_, i) { буфер[i] = Math.floor(Math.random() * 256); });
    var хвост = Array.prototype.map
      .call(буфер, function (б) { return б.toString(36).padStart(2, '0'); })
      .join('')
      .slice(0, 12);
    return префикс + '_' + Date.now().toString(36) + хвост;
  }

  function создатьОперацию(тип, авторId, данные) {
    return {
      id: новыйId('op'),
      type: тип,
      author: авторId,
      at: new Date().toISOString(),
      data: данные,
    };
  }

  /** Объединяет наборы операций без потерь и приводит к детерминированному порядку. */
  function слить() {
    var поId = Object.create(null);
    for (var i = 0; i < arguments.length; i++) {
      var набор = arguments[i] || [];
      for (var j = 0; j < набор.length; j++) {
        var оп = набор[j];
        if (оп && оп.id && !поId[оп.id]) поId[оп.id] = оп;
      }
    }
    return Object.keys(поId)
      .map(function (к) { return поId[к]; })
      .sort(function (a, b) {
        if (a.at === b.at) return a.id < b.id ? -1 : a.id > b.id ? 1 : 0;
        return a.at < b.at ? -1 : 1;
      });
  }

  /** Свёртка журнала в текущее состояние. */
  function собратьСостояние(операции) {
    var участники = Object.create(null);
    var передачи = Object.create(null);

    (операции || []).forEach(function (оп) {
      var д = оп.data || {};
      switch (оп.type) {
        case ТИПЫ.УЧАСТНИК:
          if (!д.userId) return;
          участники[д.userId] = {
            id: д.userId,
            имя: д.name || (участники[д.userId] || {}).имя || 'Без имени',
            тег: д.tagTitle || (участники[д.userId] || {}).тег || null,
            обновлён: оп.at,
          };
          return;

        case ТИПЫ.ПРЕДЛОЖЕНИЕ:
          if (!д.offerId || передачи[д.offerId]) return;
          передачи[д.offerId] = {
            id: д.offerId,
            задачаId: д.taskId,
            заголовокЗадачи: д.taskTitle || '',
            отId: д.fromId || оп.author,
            комуId: д.toId,
            сообщение: д.message || '',
            статус: 'ожидает',
            созданаВ: оп.at,
            решениеВ: null,
            причина: '',
            опПредложения: оп.id,
            опРешения: null,
          };
          return;

        case ТИПЫ.ПРИНЯТИЕ: {
          var пр = передачи[д.offerId];
          if (!пр || пр.статус !== 'ожидает') return;
          пр.статус = 'принята';
          пр.решениеВ = оп.at;
          пр.опРешения = оп.id;
          return;
        }

        case ТИПЫ.ОТКЛОНЕНИЕ: {
          var от = передачи[д.offerId];
          if (!от || от.статус !== 'ожидает') return;
          от.статус = 'отклонена';
          от.решениеВ = оп.at;
          от.причина = д.reason || '';
          от.опРешения = оп.id;
          return;
        }

        case ТИПЫ.ОТЗЫВ: {
          var оз = передачи[д.offerId];
          if (!оз || оз.статус !== 'ожидает') return;
          оз.статус = 'отозвана';
          оз.решениеВ = оп.at;
          оз.опРешения = оп.id;
          return;
        }
      }
    });

    return {
      участники: участники,
      передачи: передачи,
      списокУчастников: function () {
        return Object.keys(участники).map(function (к) { return участники[к]; });
      },
      списокПередач: function () {
        return Object.keys(передачи).map(function (к) { return передачи[к]; });
      },
    };
  }

  /** События, адресованные конкретному участнику. */
  function собратьУведомления(состояние, мойId) {
    var события = [];
    var имя = function (id) {
      return (состояние.участники[id] || {}).имя || 'неизвестный участник';
    };

    состояние.списокПередач().forEach(function (п) {
      var название = п.заголовокЗадачи || 'задача';

      if (п.комуId === мойId && п.статус === 'ожидает') {
        события.push({
          опId: п.опПредложения,
          вид: 'предложение',
          время: п.созданаВ,
          передача: п,
          текст: имя(п.отId) + ' предлагает вам задачу «' + название + '»',
        });
      }

      if (п.отId === мойId && п.опРешения) {
        if (п.статус === 'принята') {
          события.push({
            опId: п.опРешения,
            вид: 'принято',
            время: п.решениеВ,
            передача: п,
            текст: имя(п.комуId) + ' принял задачу «' + название + '»',
          });
        } else if (п.статус === 'отклонена') {
          события.push({
            опId: п.опРешения,
            вид: 'отклонено',
            время: п.решениеВ,
            передача: п,
            текст: имя(п.комуId) + ' отклонил задачу «' + название + '»'
              + (п.причина ? ': ' + п.причина : ''),
          });
        }
      }
    });

    return события.sort(function (a, b) { return a.время < b.время ? 1 : -1; });
  }

  // ---------- чтение и запись блоба плагина ----------

  function разобрать(текст) {
    if (!текст) return { version: ВЕРСИЯ_ДАННЫХ, ops: [] };
    try {
      var д = JSON.parse(текст);
      if (!д || !Array.isArray(д.ops)) return { version: ВЕРСИЯ_ДАННЫХ, ops: [] };
      return д;
    } catch (е) {
      console.warn('[Передача задач] не удалось разобрать данные плагина:', е);
      return { version: ВЕРСИЯ_ДАННЫХ, ops: [] };
    }
  }

  function сериализовать(операции) {
    return JSON.stringify({ version: ВЕРСИЯ_ДАННЫХ, ops: операции });
  }

  /**
   * Читает текущий блоб, доливает наши операции и записывает обратно.
   * Между чтением и записью могли приехать чужие операции — слияние их сохранит.
   */
  async function дописать(api, новыеОперации) {
    var текущие = разобрать(await api.loadSyncedData()).ops;
    var итог = слить(текущие, новыеОперации || []);
    await api.persistDataSynced(сериализовать(итог));
    return итог;
  }

  async function прочитать(api) {
    return разобрать(await api.loadSyncedData()).ops;
  }

  глобальный.ПередачаЗадач = {
    ТИПЫ: ТИПЫ,
    новыйId: новыйId,
    создатьОперацию: создатьОперацию,
    слить: слить,
    собратьСостояние: собратьСостояние,
    собратьУведомления: собратьУведомления,
    разобрать: разобрать,
    сериализовать: сериализовать,
    дописать: дописать,
    прочитать: прочитать,
  };
})(typeof window !== 'undefined' ? window : globalThis);
